/* Conformance: the JS Layer A must reproduce the Python reference exactly.
 *
 * Vectors are generated by tools/gen_web_assets.py from the Python
 * implementation. Any behavioural divergence between the CLI and the web build
 * fails here, which is the whole point of having this file.
 *
 * Run: node --test web/test/
 * (no dependencies, uses the built-in node:test runner)
 */

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

import { clean, scan, diffOps } from '../src/layer-a.js';

const here = dirname(fileURLToPath(import.meta.url));
const vectors = JSON.parse(
  readFileSync(join(here, '..', '..', 'conformance', 'vectors.json'), 'utf8'),
);

const opts = (o) => ({
  aggressive: o.aggressive,
  stripEmojiGlue: o.strip_emoji_glue,
  normalize: o.normalize,
});

test(`vectors file is populated (${vectors.count} cases)`, () => {
  assert.ok(vectors.count > 30, 'suspiciously few conformance cases');
  assert.equal(vectors.cases.length, vectors.count);
});

for (const c of vectors.cases) {
  test(`clean: ${c.id}`, () => {
    const got = clean(c.input, opts(c.options));
    assert.equal(got.text, c.expect.cleaned, 'cleaned text differs from Python');
    assert.equal(got.totalRemoved, c.expect.total_removed, 'removed count differs');
    assert.equal(got.totalReplaced, c.expect.total_replaced, 'replaced count differs');
    assert.deepEqual(
      got.keptLoadBearing,
      c.expect.kept_load_bearing,
      'load-bearing preservation differs from Python',
    );
  });

  test(`scan: ${c.id}`, () => {
    const got = scan(c.input, opts(c.options));
    assert.equal(got.totalFlagged, c.expect.total_flagged, 'flagged count differs');
    assert.equal(got.totalRemovable, c.expect.total_removable, 'removable count differs');
    assert.equal(
      got.watermarkSuspected,
      c.expect.watermark_suspected,
      'watermark verdict differs',
    );

    // `name` is compared too: the browser labels findings from a generated
    // table instead of the full UCD, and a missing entry would show
    // "<unnamed>" where the CLI shows a real Unicode name.
    const mine = got.findings.map((f) => ({
      codepoint: f.codepoint,
      name: f.name,
      kind: f.kind,
      count: f.count,
      kept: f.keptCount,
    }));
    assert.deepEqual(mine, c.expect.findings, 'findings differ from Python');
  });
}

/* ── properties that must hold regardless of the vectors ─────────────────── */

test('clean is idempotent across every vector', () => {
  for (const c of vectors.cases) {
    const once = clean(c.input, opts(c.options)).text;
    const twice = clean(once, opts(c.options)).text;
    assert.equal(twice, once, `not idempotent: ${c.id}`);
  }
});

test('scan agrees with clean on how much is removable', () => {
  for (const c of vectors.cases) {
    if (c.options.normalize) continue; // NFKC changes length independently
    const s = scan(c.input, opts(c.options));
    const cl = clean(c.input, opts(c.options));
    assert.equal(
      s.totalRemovable,
      cl.totalRemoved + cl.totalReplaced,
      `scan/clean disagree: ${c.id}`,
    );
  }
});

test('reported offsets point at the character claimed', () => {
  for (const c of vectors.cases) {
    const chars = Array.from(c.input);
    for (const f of scan(c.input, opts(c.options)).findings) {
      for (const off of f.offsets) {
        assert.equal(
          chars[off].codePointAt(0),
          f.codepointInt,
          `bad offset ${off} for ${f.codepoint} in ${c.id}`,
        );
      }
    }
  }
});

test('diff reconstructs exactly what clean produced', () => {
  for (const c of vectors.cases) {
    if (c.options.normalize) continue; // diff runs before normalization
    const ops = diffOps(c.input, opts(c.options));
    const rebuilt = ops
      .map((o) => (o.op === 'delete' ? '' : o.op === 'replace' ? o.with : o.text))
      .join('');
    assert.equal(rebuilt, clean(c.input, opts(c.options)).text, `diff mismatch: ${c.id}`);

    const source = ops.map((o) => o.text).join('');
    assert.equal(source, c.input, `diff lost source text: ${c.id}`);
  }
});

test('astral characters are handled as single codepoints', () => {
  // A naive UTF-16 implementation would split these and corrupt the output.
  const family = '\u{1F469}‍\u{1F467}';
  assert.equal(clean(family).text, family);

  const smuggled = 'Hi' + [...'SECRET'].map((ch) =>
    String.fromCodePoint(0xe0000 + ch.codePointAt(0))).join('');
  assert.equal(clean(smuggled).text, 'Hi');
  assert.equal(clean(smuggled).totalRemoved, 6);
});

test('empty and whitespace-only inputs do not throw', () => {
  for (const s of ['', ' ', '\n', '\t\t', '   \n  ']) {
    assert.equal(clean(s).text, s);
    assert.equal(scan(s).findings.length, 0);
  }
});
